import uuid

import pytest

import bedrock_protocol
from bedrock_protocol import v748, v786, v818, v898, v975, v1001, v2168, v2193, v2225

# generated by gophertunnel b8bd735:
# &packet.CommandRequest{CommandLine: "/say hi", CommandOrigin: protocol.CommandOrigin{
#   Origin: protocol.CommandOriginAutomationPlayer,
#   UUID: uuid.MustParse("01234567-89ab-cdef-fedc-ba9876543210"), RequestID: "req-1",
#   PlayerUniqueID: -2}, Internal: true,
#   Version: "testforblockcommanddoesnotignoreblockstate"}
AUTOMATION_PLAYER = bytes.fromhex(
    "072f736179206869106175746f6d6174696f6e706c61796572efcdab89674523011032547698badcfe057265712d31feffffffffffffff012a74657374666f72626c6f636b636f6d6d616e64646f65736e6f7469676e6f7265626c6f636b7374617465"
)

# generated by gophertunnel b8bd735:
# &packet.CommandRequest{CommandLine: strings.Repeat("a", 127),
#   CommandOrigin: protocol.CommandOrigin{Origin: protocol.CommandOriginPlayer}, Version: "initial"}
COMMAND_127 = (
    bytes.fromhex("7f")
    + bytes.fromhex("61") * 127
    + bytes.fromhex("06706c61796572000000000000000000000000000000000000000000000000000007696e697469616c")
)

# generated by gophertunnel b8bd735:
# &packet.CommandRequest{CommandLine: strings.Repeat("a", 128),
#   CommandOrigin: protocol.CommandOrigin{Origin: protocol.CommandOriginPlayer}, Version: "initial"}
COMMAND_128 = (
    bytes.fromhex("8001")
    + bytes.fromhex("61") * 128
    + bytes.fromhex("06706c61796572000000000000000000000000000000000000000000000000000007696e697469616c")
)

# generated by gophertunnel b8bd735:
# &packet.CommandRequest{CommandOrigin: protocol.CommandOrigin{
#   Origin: protocol.CommandOriginPlayer, PlayerUniqueID: 0}, Version: "initial"}
PLAYER_ID_ZERO = bytes.fromhex("0006706c61796572000000000000000000000000000000000000000000000000000007696e697469616c")

# generated by gophertunnel b8bd735:
# &packet.CommandRequest{CommandOrigin: protocol.CommandOrigin{
#   Origin: protocol.CommandOriginPlayer, PlayerUniqueID: -1}, Version: "initial"}
PLAYER_ID_NEGATIVE = bytes.fromhex(
    "0006706c617965720000000000000000000000000000000000ffffffffffffffff0007696e697469616c"
)

# generated by gophertunnel b8bd735:
# &packet.CommandRequest{CommandOrigin: protocol.CommandOrigin{Origin: protocol.CommandOriginPlayer},
#   Version: "latest"}
LATEST = bytes.fromhex("0006706c617965720000000000000000000000000000000000000000000000000000066c6174657374")

# LATEST with Version: "clonepartialbedblockfix"
CLONE_PARTIAL_BED_BLOCK_FIX = LATEST.removesuffix(b"\x06latest") + b"\x17clonepartialbedblockfix"

GOLDENS = [
    pytest.param(
        v2168.CommandRequestPacket(
            command="/say hi",
            origin=v2168.CommandOriginData(
                type=v2168.CommandOriginType.AUTOMATION_PLAYER,
                uuid=uuid.UUID("01234567-89ab-cdef-fedc-ba9876543210"),
                request_id="req-1",
                player_id=-2,
            ),
            internal_source=True,
            version=v2168.CurrentCmdVersion.TEST_FOR_BLOCK_COMMAND_DOES_NOT_IGNORE_BLOCK_STATE,
        ),
        AUTOMATION_PLAYER,
        id="automation-player",
    ),
    pytest.param(
        v2168.CommandRequestPacket(
            command="a" * 127,
            origin=v2168.CommandOriginData(type=v2168.CommandOriginType.PLAYER),
            version=v2168.CurrentCmdVersion.INITIAL,
        ),
        COMMAND_127,
        id="127-byte-command-takes-a-one-byte-length",
    ),
    pytest.param(
        v2168.CommandRequestPacket(
            command="a" * 128,
            origin=v2168.CommandOriginData(type=v2168.CommandOriginType.PLAYER),
            version=v2168.CurrentCmdVersion.INITIAL,
        ),
        COMMAND_128,
        id="128-byte-command-takes-a-two-byte-length",
    ),
    pytest.param(
        v2168.CommandRequestPacket(
            origin=v2168.CommandOriginData(type=v2168.CommandOriginType.PLAYER, player_id=0),
            version=v2168.CurrentCmdVersion.INITIAL,
        ),
        PLAYER_ID_ZERO,
        id="player-id-zero",
    ),
    pytest.param(
        v2168.CommandRequestPacket(
            origin=v2168.CommandOriginData(type=v2168.CommandOriginType.PLAYER, player_id=-1),
            version=v2168.CurrentCmdVersion.INITIAL,
        ),
        PLAYER_ID_NEGATIVE,
        id="player-id-below-zero-is-eight-fixed-bytes",
    ),
    *[
        pytest.param(
            version.CommandRequestPacket(
                origin=version.CommandOriginData(type=version.CommandOriginType.PLAYER),
                version=version.CurrentCmdVersion.LATEST,
            ),
            LATEST,
            id=f"{version.__name__.rpartition('.')[2]}-latest",
        )
        for version in (v2168, v2193, v2225)
    ],
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_command_request_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_command_request_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    ("version", "latest"),
    [
        pytest.param(v748, 42, id="v748"),
        pytest.param(v786, 43, id="v786"),
        pytest.param(v818, 44, id="v818"),
        pytest.param(v898, 45, id="v898"),
        pytest.param(v975, 46, id="v975"),
        pytest.param(v1001, 49, id="v1001"),
        pytest.param(v2168, 50, id="v2168"),
        pytest.param(v2193, 52, id="v2193"),
        pytest.param(v2225, 55, id="v2225"),
    ],
)
def test_each_era_numbers_its_latest_command_version(version, latest):
    assert latest == version.CurrentCmdVersion.LATEST


def test_2225_count_is_56():
    assert v2225.CurrentCmdVersion.COUNT == 56


def test_2168_refuses_a_command_version_bds_does_not_name():
    with pytest.raises(bedrock_protocol.DecodeError, match=r"^CommandRequestPacket\.version: unknown value"):
        v2168.CommandRequestPacket.from_bytes(CLONE_PARTIAL_BED_BLOCK_FIX)
